// DeploymentOpenGraph: A deployment's home page as a link bot reads it: one plain GET of `/` with no
// JavaScript, following redirects on the same host, reading the first megabyte. Tags set by JavaScript after
// the page loads are not here, as link bots don't see them either. URLs are absolute (resolved against the
// deployment's `url`) and http(s) only; a value that isn't one is null. A page that isn't HTML (an API) has
// every field null.
type DeploymentOpenGraph struct {
	// `og:title`, else `<title>`.
	Title *string `json:"title"`
	// `og:description`, else `<meta name="description">`.
	Description *string `json:"description"`
	// `og:image` (or `og:image:url`, `og:image:secure_url`). The dashboard loads it from its host; the API
	// does not fetch it.
	Image *string `json:"image"`
	// The page wrote `og:image` as a relative URL. Some link bots don't resolve it, so the image may not
	// show.
	ImageWasRelative bool `json:"image_was_relative"`
	// `og:url`, else `<link rel="canonical">`.
	URL *string `json:"url"`
	// `og:site_name`.
	SiteName *string `json:"site_name"`
	// `twitter:card` as written (`summary`, `summary_large_image`, …). Null means X shows a small summary
	// card.
	TwitterCard *string `json:"twitter_card"`
	// `twitter:title`; X uses it over `title`.
	TwitterTitle *string `json:"twitter_title"`
	// `twitter:description`; X uses it over `description`.
	TwitterDescription *string `json:"twitter_description"`
	// `twitter:image`; X uses it over `image`.
	TwitterImage *string `json:"twitter_image"`
	// `<link rel="icon">`. Null when the page declares none; most sites still serve `/favicon.ico`.
	Favicon *string `json:"favicon"`
	// When the builder read the page.
	FetchedAt time.Time `json:"fetched_at"`
}

